import re

from moler.exceptions import ParsingDone, CommandFailure
from ta_moler.cmd.egen.genericegen import GenericEgen


class DevmemWrite(GenericEgen):
    """Devmem command class."""

    def __init__(self, connection, options, devmem_path='devmem', prompt=None, newline_chars=None, runner=None):
        """
        Devmem command.

        :param connection: moler connection to device, terminal when command is executed.
        :param devmem_path: path to devmem command.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(DevmemWrite, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.devmem_path = devmem_path
        self.current_cmd_options = ""
        self.last_sent = False
        self._value_parsed = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        self.current_cmd_options = self.options.pop(0)
        cmd = f"{self.devmem_path} {self.current_cmd_options}"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_key_value(line)
            except ParsingDone:
                pass
        else:
            if 0 == len(self.options):
                self.last_sent = True
            if self._regex_helper.search_compiled(self._re_prompt, line) and len(self.options):
                if self.current_cmd_options in self.current_ret.keys() and self._value_parsed:
                    cmd = self.build_command_string()
                    self.connection.sendline(cmd)
                    self._value_parsed = False

        return super(DevmemWrite, self).on_new_line(line, is_full_line)

    _re_key_value = re.compile(r"(?P<KEY>.*): (?P<VALUE>.*)")

    def _parse_key_value(self, line):
        """
        Parse pair KEY: VALUE from line.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(DevmemWrite._re_key_value, line):
            key = self._regex_helper.group("KEY")
            value = self._regex_helper.group("VALUE")

            if value == "FAILED":
                self.command_string = self.devmem_path
                self.set_exception(CommandFailure(self, f"ERROR: For options: '{self.current_cmd_options}' status for '{key}' is '{value}'!"))
            else:
                if self.current_cmd_options not in self.current_ret.keys():
                    self.current_ret[self.current_cmd_options] = {}
                self.current_ret[self.current_cmd_options][key] = value

            self._value_parsed = True
            raise ParsingDone

    def is_end_of_cmd_output(self, line):
        """
        Check if end of command is reached.

        :param line: Line from device.
        :return: True if end of command is reached, False otherwise
        """
        if len(self.options) == 0 and self.last_sent:
            if self._regex_helper.search_compiled(self._re_prompt, line):
                return True
        return False


